'use strict';
const $=id=>document.getElementById(id);let edition=null,all=[],filtered=[],visibleCount=24;
const catalogGroups=[['Daily cooking',["Children's Food",'Meats','Fish, Poultry, and Game','Vegetables and Soups','Meat Substitutes, Pasta, and Rice']],['Breads & morning table',['Breads, Griddle Cakes and Waffles','Biscuits and Shortcake','Quick Breads','Muffins','Beverages']],['Cakes, cookies & sweets',['Cakes With Butter','Cakes Without Butter','Drop Cookies','Cold Desserts','Hot Desserts','Icebox Desserts','Pastry']],['Salads & sandwiches',['Salads','Molded Salads','Salad Dressings','Sandwiches']],['Pantry & preserving',['Preserves, Pickles, and Relishes','Confections','Cake Fillings and Icings','Dessert Sauces']],['More chapters',['Gingerbread','Rolled Cookies','Slice-and-Bake Cookies and Bars','Doughnuts','Frozen Desserts','Advertising recipes (Royal Baking Powder)']]];
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}function norm(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function chapterCounts(){const counts=new Map();for(const recipe of all)for(const chapter of recipe.categories||[])counts.set(chapter,(counts.get(chapter)||0)+1);return counts;}
function populateChapters(){const counts=chapterCounts();for(const chapter of [...counts.keys()].sort((a,b)=>a.localeCompare(b))){const option=el('option',`${chapter} (${counts.get(chapter)})`);option.value=chapter;$('chapter').append(option);}const root=$('catalog-groups');root.replaceChildren();const listed=new Set(catalogGroups.flatMap(([,chapters])=>chapters));const groups=[...catalogGroups];const extra=[...counts.keys()].filter(name=>!listed.has(name));if(extra.length)groups.push(['Other chapters',extra]);for(const[heading,chapters]of groups){const section=el('section',undefined,'catalog-group');section.append(el('h3',heading));const list=el('ul');for(const chapter of chapters.filter(name=>counts.has(name))){const item=el('li'),button=el('button');button.type='button';button.append(document.createTextNode(chapter),el('span',String(counts.get(chapter))));button.onclick=()=>{$('chapter').value=chapter;$('search').value='';search();$('browse').scrollIntoView({block:'start'});};item.append(button);list.append(item);}section.append(list);root.append(section);}}
function queryTerms(){const words=norm($('search').value).trim().split(/\s+/).filter(Boolean);return{include:words.filter(word=>!word.startsWith('-')),exclude:words.filter(word=>word.startsWith('-')&&word.length>1).map(word=>word.slice(1))};}
function search(){if(!edition)return;visibleCount=24;const{include,exclude}=queryTerms(),chapter=$('chapter').value,sourceFilter=$('source-filter').value,includeSource=$('include-source').checked;filtered=all.filter(recipe=>{const source=recipe.source||{},sourceText=includeSource?` ${recipe.notes||''} ${recipe.source_id||''} ${JSON.stringify(source)}`:'';return(!chapter||recipe.categories?.includes(chapter))&&(!sourceFilter||(sourceFilter==='contributor'&&source.contributors?.length)||(sourceFilter==='printed-page'&&source.printed_page))&&include.every(term=>(recipe.searchText+sourceText).includes(term))&&exclude.every(term=>!(recipe.searchText+sourceText).includes(term));});filtered.sort((a,b)=>a.title.localeCompare(b.title));const labels=[];if(include.length)labels.push(`matching ${include.join(', ')}`);if(exclude.length)labels.push(`without ${exclude.join(', ')}`);$('search-status').textContent=labels.length?`${filtered.length} recipes ${labels.join(' · ')}.`:'Tip: put a minus sign before an ingredient you do not want, such as -sugar.';$('result-count').textContent=`${filtered.length} ${filtered.length===1?'recipe':'recipes'}`;$('results-title').textContent=labels.length||chapter||sourceFilter?'Search results':'Recipes';renderCards();}
function renderCards(){const root=$('cards');root.replaceChildren();const results=filtered.slice(0,visibleCount);$('show-more').hidden=visibleCount>=filtered.length;$('result-count').textContent=`Showing ${results.length} of ${filtered.length} ${filtered.length===1?'recipe':'recipes'}`;if(!results.length){root.append(el('p','No recipes found. Try another ingredient, chapter, or shorter title.'));return;}for(const recipe of results){const link=el('a',undefined,'recipe-card');link.href=`#recipe/${recipe.id}`;link.append(el('p',recipe.categories?.[0]||'Recipe','chapter'),el('h3',recipe.title));const source=recipe.source||{};if(source.contributors?.length||source.printed_page)link.append(el('p',[source.contributors?.join(', '),source.printed_page?`Printed page ${source.printed_page}`:''].filter(Boolean).join(' · '),'source'));root.append(link);}}
function showRecipe(recipe){$('browse').hidden=true;$('detail').hidden=false;const source=recipe.source||{},content=$('recipe-content');content.replaceChildren();content.append(el('p',[recipe.categories?.[0],source.printed_page?`Printed page ${source.printed_page}`:''].filter(Boolean).join(' · '),'chapter'),el('h1',recipe.title));if(recipe.description)content.append(el('p',recipe.description,'recipe-description'));const layout=el('div',undefined,'recipe-layout'),ingredients=el('section',undefined,'ingredients'),method=el('section',undefined,'method');ingredients.append(el('h2','Ingredients'));const ingredientList=el('ul');for(const line of recipe.ingredients||[])ingredientList.append(el('li',line));ingredients.append(ingredientList);method.append(el('h2','Directions'));const steps=el('ol');for(const step of recipe.steps||[])steps.append(el('li',step.replace(/\s+---\s*$/,'')));method.append(steps);layout.append(ingredients,method);content.append(layout);const facts=['Edited Version 8',`Source ID: ${recipe.source_id}`];if(source.pdf_page)facts.push(`PDF page ${source.pdf_page}`);if(source.printed_page)facts.push(`Printed page ${source.printed_page}`);if(source.contributors?.length)facts.push(`Contributor: ${source.contributors.join(', ')}`);content.append(el('p',facts.join(' · '),'source-note'));document.title=`${recipe.title} · Mayflower Guild Cookbook (1930)`;window.scrollTo(0,0);}
function route(){const match=location.hash.match(/^#recipe\/(\d+)$/);if(match){const recipe=all.find(item=>item.id===Number(match[1]));if(recipe){showRecipe(recipe);return;}}$('browse').hidden=false;$('detail').hidden=true;document.title='Mayflower Guild Cookbook (1930)';}
function setTextSize(size){$('recipe-content').style.setProperty('--reading-size',`${size}px`);document.querySelectorAll('[data-text-size]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.textSize)===size)));}
async function loadRecipeEdition(){const message='The recipe edition could not be loaded. Please try again.',manifestResponse=await fetch('data/edition.json',{cache:'no-cache'});if(!manifestResponse.ok)throw Error(message);const manifest=await manifestResponse.json(),hash=manifest.files?.['recipes.json'];if(!/^[a-f0-9]{64}$/.test(hash))throw Error(message);const response=await fetch(`data/recipes.json?v=${hash}`,{cache:'force-cache'});if(!response.ok)throw Error(message);return response.json();}
(async()=>{try{edition=await loadRecipeEdition();all=edition.recipes.map(recipe=>({...recipe,searchText:norm([recipe.title,recipe.description,...(recipe.ingredient_search_terms||[]),...(recipe.ingredients||[]),...(recipe.steps||[])].join(' '))}));populateChapters();search();route();}catch(error){$('error').hidden=false;$('error').textContent=error.message;}})();
$('search-form').onsubmit=event=>{event.preventDefault();search();};for(const id of['search','chapter','source-filter','include-source'])$(id).addEventListener(id==='search'?'input':'change',search);for(const button of document.querySelectorAll('[data-text-size]'))button.onclick=()=>setTextSize(Number(button.dataset.textSize));$('print').onclick=()=>window.print();window.addEventListener('hashchange',route);

$('show-more').onclick=()=>{const firstNew=visibleCount;visibleCount+=24;renderCards();$('cards').children[firstNew]?.focus();};
